const $=s=>document.querySelector(s),cats=['Software','Marketing','Travel','Office','Other'],colors=['#1fbef8','#727cf5','#46c9ac','#eab96c','#8b9dbb'];
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n),today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=[],budgets={},view='overview',editing=null,ready=false,busy=false;
$('#month').value=today().slice(0,7);$('#category').innerHTML='<option value="">All categories</option>'+cats.map(c=>`<option>${c}</option>`).join('');$('#expense-form [name=category]').innerHTML=cats.map(c=>`<option>${c}</option>`).join('');
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
async function api(action,payload={}){const response=await fetch('/api/workspace',{method:action?'POST':'GET',headers:action?{'Content-Type':'application/json'}:{},credentials:'same-origin',body:action?JSON.stringify({action,...payload}):undefined});const result=await response.json().catch(()=>({error:'Unable to read the server response.'}));if(!response.ok){if(response.status===401){ready=false;data=[];budgets={};render();connection('Sign in required');if(!$('#login').open)$('#login').showModal()}throw new Error(result.error||'Unable to connect. Please try again.')}return result}
function connection(message){$('#connection').textContent=message;$('#add').disabled=!ready;$('#export').disabled=!ready;$('#signout').hidden=!ready}
function applyState(state){data=state.expenses;budgets=state.budgets;render()}
async function load(){ready=false;connection('Connecting…');$('#load-error').hidden=true;try{const state=await api();ready=true;applyState(state);connection('Neon connected')}catch(error){connection('Connection unavailable');if(!$('#login').open){$('#load-error span').textContent=error.message;$('#load-error').hidden=false}}}
async function mutate(action,payload){if(!ready||busy)return false;busy=true;try{const state=await api(action,payload);applyState(state);return true}catch(error){notify(error.message);return false}finally{busy=false}}
function selected(){return data.filter(e=>e.date.startsWith($('#month').value))}
function filtered(){return selected().filter(e=>(!$('#category').value||e.category===$('#category').value)&&(!$('#status').value||e.status===$('#status').value)&&`${e.description} ${e.notes||''}`.toLowerCase().includes($('#search').value.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date))}
function render(){const list=selected(),total=list.reduce((s,e)=>s+e.amount,0),pending=list.filter(e=>e.status==='Pending').reduce((s,e)=>s+e.amount,0),sums=cats.map(c=>list.filter(e=>e.category===c).reduce((s,e)=>s+e.amount,0)),budget=cats.reduce((s,c)=>s+(Number(budgets[c])||0),0),month=$('#month').value;const date=new Date(month+'-01T12:00:00');$('#period-label').textContent=date.toLocaleDateString('en-US',{month:'long',year:'numeric'});$('#count').textContent=data.length;
$('#stats').innerHTML=[['Total expenses',money(total),'Recorded this month','↗'],['Paid expenses',money(total-pending),'Payments completed','✓'],['Pending payments',money(pending),list.filter(e=>e.status==='Pending').length+' awaiting payment','◷'],['Budget remaining',budget?money(budget-total):'Not set',budget?money(budget)+' monthly budget':'Set your category budgets','◈']].map(([label,val,sub,icon])=>`<article class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><strong>${val}</strong><small>${sub}</small></article>`).join('');
const days=new Date(date.getFullYear(),date.getMonth()+1,0).getDate(),daily=Array.from({length:days},(_,i)=>list.filter(e=>Number(e.date.slice(-2))===i+1).reduce((s,e)=>s+e.amount,0)),max=Math.max(...daily,1);$('#chart').innerHTML=daily.map((v,i)=>`<div class="bar" style="height:${Math.max(1,v/max*100)}%;opacity:${v?1:.15}" title="${month}-${String(i+1).padStart(2,'0')}: ${money(v)}"></div>`).join('');$('#last-day').textContent=days;$('#donut-total').textContent=money(total);let start=0;const stops=sums.map((s,i)=>{let end=start+(total?s/total*100:0);const stop=`${colors[i]} ${start}% ${end}%`;start=end;return stop});$('#donut').style.background=total?`conic-gradient(${stops.join(',')})`:'#1e304a';$('#categories').innerHTML=cats.map((c,i)=>`<div class="category-row"><i style="background:${colors[i]}"></i>${c}<b>${money(sums[i])}</b></div>`).join('');
const rows=filtered();$('#result-count').textContent=rows.length+' records';$('#rows').innerHTML=rows.length?rows.map(e=>`<tr><td><div class="expense-cell"><span class="expense-icon">${esc(e.description.charAt(0).toUpperCase())}</span><span>${esc(e.description)}</span></div></td><td>${esc(e.category)}</td><td>${new Date(e.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</td><td><span class="badge ${e.status==='Pending'?'pending':''}">${esc(e.status)}</span></td><td class="amount">${money(e.amount)}</td><td><button class="row-action" data-edit="${e.id}" aria-label="Edit ${esc(e.description)}">Edit</button><button class="row-action" data-delete="${e.id}" aria-label="Delete ${esc(e.description)}">×</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No expenses here yet. Add an expense to get started.</td></tr>';$('#footer-count').textContent=rows.length+' expenses · '+money(rows.reduce((s,e)=>s+e.amount,0));
$('#budget-view').innerHTML=`<article class="card"><div class="card-head"><div><h2>Monthly category budgets</h2><p>Set a recurring monthly limit for each category. Changes save automatically.</p></div></div>${cats.map((c,i)=>{const limit=Number(budgets[c])||0;return `<div class="budget-row"><div><span>${c} <small>${money(sums[i])} spent${limit&&sums[i]>limit?' · Over budget':''}</small></span><label>USD <input class="budget-edit" type="number" min="0" max="999999999" step="0.01" data-budget="${c}" aria-label="${c} monthly budget" value="${limit}" /></label></div><progress value="${Math.min(sums[i],limit)||0}" max="${limit||1}"></progress></div>`}).join('')}</article>`;
$('#overview').hidden=view!=='overview';$('#budget-view').hidden=view!=='budgets';$('#transaction-view').hidden=view==='budgets';$('#title').textContent={overview:'Expense overview',expenses:'All expenses',budgets:'Monthly budgets'}[view];$('#crumb').textContent={overview:'Overview',expenses:'All expenses',budgets:'Budgets'}[view];$('#table-title').textContent=view==='expenses'?'All expenses':'Recent expenses';}
function openEditor(id){editing=id||null;const f=$('#expense-form');f.reset();f.elements.date.value=today();if(id){const e=data.find(x=>x.id===id);for(const k of ['description','amount','date','category','status','notes'])f.elements[k].value=e[k]||''}$('#modal-title').textContent=id?'Edit expense':'Add expense';$('#editor').showModal()}
$('#add').onclick=()=>{if(ready&&!busy)openEditor()};$('#close').onclick=$('#cancel').onclick=()=>$('#editor').close();$('#expense-form').onsubmit=async e=>{e.preventDefault();const f=e.target,amount=Number(f.elements.amount.value);if(!Number.isFinite(amount)||amount<=0)return;const item={id:editing||crypto.randomUUID(),description:f.elements.description.value.trim(),amount,date:f.elements.date.value,category:f.elements.category.value,status:f.elements.status.value,notes:f.elements.notes.value.trim()};if(!item.description)return f.elements.description.focus();const button=f.querySelector('button.primary');button.disabled=true;try{if(await mutate('saveExpense',{expense:item})){$('#month').value=item.date.slice(0,7);$('#editor').close();render();notify(editing?'Expense updated':'Expense added')}}finally{button.disabled=false}};

document.addEventListener('click',async e=>{const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]'),nav=e.target.closest('[data-view]');if(edit&&ready&&!busy)openEditor(edit.dataset.edit);if(del&&ready&&!busy&&confirm('Delete this expense?')){if(await mutate('deleteExpense',{id:del.dataset.delete}))notify('Expense deleted')}if(nav){view=nav.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b===nav));render()}});
document.addEventListener('change',async e=>{if(e.target.matches('[data-budget]')){const n=Number(e.target.value);if(!e.target.checkValidity()||!Number.isFinite(n))return;if(!await mutate('saveBudget',{category:e.target.dataset.budget,amount:n}))render()}});for(const s of ['#month','#category','#status'])$(s).onchange=()=>{if($('#month').value)render()};$('#search').oninput=render;
$('#export').onclick=()=>{const rows=filtered();const csv=[['Description','Amount (USD)','Date','Category','Status','Notes'],...rows.map(e=>[e.description,e.amount,e.date,e.category,e.status,e.notes||''])].map(row=>row.map(v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=`PrimeSphere-expenses-${$('#month').value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Expense export downloaded')};
$('#login').addEventListener('cancel',e=>e.preventDefault());
$('#login-form').onsubmit=async e=>{e.preventDefault();const b=$('#login-submit');b.disabled=true;$('#login-error').textContent='';try{await api('login',{password:e.target.elements.password.value});e.target.reset();$('#login').close();await load()}catch(error){$('#login-error').textContent=error.message}finally{b.disabled=false}};
$('#signout').onclick=async()=>{try{await api('logout');ready=false;data=[];budgets={};render();connection('Signed out');$('#login').showModal()}catch(error){notify(error.message)}};$('#retry').onclick=load;render();load();